package com.pulseim.message;
import com.fasterxml.jackson.databind.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import java.net.*; import java.net.http.*; import java.util.*;
@Component class ConversationMemberClient { private final String base; private final ObjectMapper json; private final HttpClient http=HttpClient.newHttpClient(); ConversationMemberClient(@Value("${pulseim.conversation-service-uri:http://localhost:8084}")String base,ObjectMapper json){this.base=base;this.json=json;} List<String> members(String token,String conversationId){try{HttpRequest r=HttpRequest.newBuilder(URI.create(base+"/api/conversations/"+URLEncoder.encode(conversationId,java.nio.charset.StandardCharsets.UTF_8)+"/members")).header("Authorization",token).GET().build();JsonNode data=json.readTree(http.send(r,HttpResponse.BodyHandlers.ofString()).body()).path("data");List<String> out=new ArrayList<>();data.forEach(n->out.add(n.path("userId").asText()));return out;}catch(Exception e){throw new IllegalStateException("Cannot read conversation members",e);}}}